FrozenFunctionalVirial wrap_a(const PWProblem& p, const FinalBandState& b,
                              cpu::xc::XCType x, const EwaldSummation& e,
                              XCBuilder& s) {
    ++trace::counts.assembly;
    trace::shared_bands.state = &b;
    trace::shared_bands.ionic = &e;
    trace::shared_bands.payload = bands_payload(b);
    auto& observed=trace::shared_bands;
    for(const auto& block:b.local_blocks)for(double f:block.occupations)observed.fcounts[block.spin]+=block.k_weight*f;
