    int g0=-1;for(std::size_t g=0;g<p.gv0.h.size();++g)if(p.gv0.h[g]==0&&p.gv0.k[g]==0&&p.gv0.l[g]==0)g0=int(g);
    if(g0<0)throw std::runtime_error("observed density G0 missing");
    if(p.ws.nspin==2)for(int spin=0;spin<2;++spin)observed.rho_counts[spin]=b.orbital_spin_density_G[spin][g0].real()*p.vol_bohr;
    else observed.rho_counts[0]=b.orbital_density_G[g0].real()*p.vol_bohr;
