        h(1, 2) = .1;
        h(2, 2) = recipe.isolated_h3 ? 5.8 : 3.8;
        f.box.set_cell(h);
    } else if (recipe.fixed()) {
        Mat3 h;constexpr double columns[3][3]={{.10,2.70,2.65},{2.75,.05,2.70},{2.65,2.75,.15}};
        for(int c=0;c<3;++c)for(int row=0;row<3;++row)h(row,c)=columns[c][row];f.box.set_cell(h);
    } else f.box = cpu::Box::cubic(6);
    constexpr double h[3][3] = {
        {1.2, 1.1, 1}, {2.1, 1.6, 1.3}, {1.6, 2.25, 1.8}};
    const double si[2][3]={{recipe.fixed()?.2:2,recipe.fixed()?.3:2,recipe.fixed()?.4:2},{recipe.fixed()?1.57:3.8,recipe.fixed()?1.66:3.2,recipe.fixed()?1.75:3}};
    for (int i = 0; i < p.nat; ++i) {
        f.span(kAtom_type)[i] = p.spin ? 1 : 14;
        f.span(kAtom_tag)[i] = i + 1;
        f.span(kAtom_mass)[i] = p.spin ? 1.008 : 28.0855;
        f.span(kAtom_x)[i] = p.spin ? h[i][0] : si[i][0];
        f.span(kAtom_y)[i] = p.spin ? h[i][1] : si[i][1];
        f.span(kAtom_z)[i] = p.spin ? h[i][2] : si[i][2];
        f.span(kAtom_fx)[i] = 10 + i;
        f.span(kAtom_fy)[i] = 20 + i;
        f.span(kAtom_fz)[i] = 30 + i;
    }
    f.meta.get(kEnergy) = 123;
    f.meta.get(kEnergyElectronic) = 456;
